insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_91_v1'
from (values
('127.720.d.1.A',3,'In an independent study course, a student draws on what they already know to design a new app for tracking recycling. This applies existing knowledge to promote:','["creativity in designing a new technology product", "avoiding all planning", "copying a finished product", "deleting old files"]'::jsonb,0,'Prior knowledge fuels new design ideas.','original'),
('127.720.d.1.A',4,'Which habit best promotes creativity when designing a new technology product?','["Waiting for someone to assign ideas", "Combining known skills in new ways to meet a real need", "Repeating the same design every time", "Avoiding any research"]'::jsonb,1,'Creativity builds on knowledge and need.','original'),
('127.720.d.1.B',3,'An independent study student keeps a calendar of milestones and checks industry news for new tools. This is tracking:','["only lunch times", "only passwords", "trends and timelines for the project", "only desk locations"]'::jsonb,2,'Timelines and trends guide the project.','original'),
('127.720.d.1.B',4,'Reviewing and evaluating a project''s progress against its timeline at set intervals helps a student to:','["skip the final product", "avoid all deadlines", "hide problems", "catch delays early and adjust the plan"]'::jsonb,3,'Regular reviews keep a study on track.','original'),
('127.720.d.1.C',3,'A student saves dated screenshots, a progress log and drafts in a shared folder. This is:','["electronic documentation of project progress", "a network outage", "a license purchase", "a hardware repair"]'::jsonb,0,'Documentation shows the project''s growth.','original'),
('127.720.d.1.C',4,'A good electronic progress record for an independent study includes:','["blank pages", "dates, work completed and next steps", "only a title", "unrelated jokes"]'::jsonb,1,'Complete records show real progress.','original'),
('127.720.d.1.D',3,'A student shows an early prototype to a teacher and an industry mentor and asks what to improve. This is:','["quitting the study", "ignoring feedback", "seeking input from peers and professionals", "hiding the work"]'::jsonb,2,'Feedback shapes technology decisions.','original'),
('127.720.d.1.D',4,'When a mentor suggests a change that conflicts with the student''s plan, a mature response is to:','["reject it automatically", "ignore the mentor", "argue until the mentor leaves", "consider the input and decide how to respond"]'::jsonb,3,'Thoughtful responses to input improve outcomes.','original'),
('127.720.d.1.E',3,'After a review, a student fixes the problems found and then moves on to the next phase. This is:','["making revisions and proceeding to the next stage", "restarting forever", "hiding the problems", "dropping the project"]'::jsonb,0,'Revise, then advance.','original'),
('127.720.d.1.E',4,'A student whose test results show the product meets every requirement should:','["revise everything again", "proceed to the next stage of study", "restart from scratch", "delete the product"]'::jsonb,1,'If criteria are met, move on.','original'),
('127.720.d.1.F',3,'In a project report, a student correctly uses terms such as bandwidth, interface and database. This is:','["writing in code only", "using slang only", "using appropriate technology terminology", "avoiding detail"]'::jsonb,2,'Precise terms show understanding.','original'),
('127.720.d.1.F',4,'Using accurate technology terms in an independent study helps the student to:','["confuse the audience", "avoid questions", "shorten the day", "communicate clearly with professionals"]'::jsonb,3,'Shared vocabulary improves communication.','original'),
('127.720.d.1.G',3,'A student builds a tool that combines several apps in a way no tutorial shows. This reflects:','["advanced creativity and innovation in technology applications", "a routine copy", "a simple restart", "a deleted file"]'::jsonb,0,'Innovation goes beyond the standard.','original'),
('127.720.d.1.G',4,'Which project shows advanced innovation rather than routine use?','["Opening a browser", "Designing a new workflow that automates a repeated school task", "Typing a document", "Printing a page"]'::jsonb,1,'Innovation solves problems in new ways.','original'),
('127.720.d.1.H',3,'A student''s program crashes, so they test pieces separately and ask a mentor about the error. This is:','["avoiding the problem", "deleting the program", "identifying and solving a problem with peer and professional input", "blaming the computer"]'::jsonb,2,'Problem solving can use outside help.','original'),
('127.720.d.1.H',4,'When individual troubleshooting fails, the best next step is to:','["start a new topic", "hide the error", "give up", "get input from peers or professionals"]'::jsonb,3,'Collaboration helps solve hard problems.','original'),
('127.720.d.1.I',3,'A student designing a web page for a business checks it against accessibility and style guidelines used in the field. This develops a product that meets:','["standards of the selected profession", "no standards", "random rules", "personal taste only"]'::jsonb,0,'Professional standards guide quality.','original'),
('127.720.d.1.I',4,'A technology product is considered professional quality when it:','["looks different from everything", "meets the standards set by its discipline or industry", "is finished quickly", "has the longest code"]'::jsonb,1,'Quality is measured against standards.','original'),
('127.720.d.1.J',3,'A student writes an original program, tests it and publishes it as a downloadable app. This is:','["hiding the program", "copying a program", "producing original work and publishing it electronically", "deleting the program"]'::jsonb,2,'Original solutions can be published digitally.','original'),
('127.720.d.1.J',4,'Original work in an independent study should:','["avoid any audience", "stay unfinished", "be copied from a classmate", "solve an identified problem and be shared electronically"]'::jsonb,3,'Originality and publication both matter.','original'),
('127.720.d.2.A',3,'A student prepares a report to match the required file type, page size and resolution. This is:','["formatting a project to output specifications", "printing blank pages", "ignoring requirements", "random layout"]'::jsonb,0,'Output specs set format requirements.','original'),
('127.720.d.2.A',4,'If a specification calls for 300 dpi images, the student must:','["shrink them to icons", "export the images at that resolution", "use any resolution", "delete the images"]'::jsonb,1,'Specs must be followed exactly.','original'),
('127.720.d.2.B',3,'A student presents findings to a panel of professionals and listens to their comments. This is:','["a private diary", "a quiet nap", "presenting to a panel for comment and professional response", "a rehearsal alone"]'::jsonb,2,'Panels give expert feedback.','original'),
('127.720.d.2.B',4,'The most useful way to use a panel''s comments is to:','["ignore the panel", "leave early", "argue with each one", "note them and use them to improve the project"]'::jsonb,3,'Feedback drives improvement.','original'),
('127.720.d.2.C',3,'A student decides whether a class-wide demo or a website best shows their results. This is:','["choosing the best method of presenting or publishing", "avoiding an audience", "deleting results", "picking at random"]'::jsonb,0,'The method should fit audience and purpose.','original'),
('127.720.d.2.C',4,'The best way to present findings to a community group with limited internet access is probably:','["a source code dump", "a printed handout and in-person demo", "a streaming-only site", "a hidden file"]'::jsonb,1,'Presentation method follows the audience.','original'),
('127.720.d.2.D',3,'Publishing the same research as a PDF report and a short video is:','["copying a rival", "deleting research", "synthesizing information in print and digital formats", "avoiding publishing"]'::jsonb,2,'Multiple formats reach more people.','original'),
('127.720.d.2.D',4,'Publishing information in both print and digital formats mainly helps to:','["lower quality", "hide findings", "reduce accuracy", "reach audiences who prefer different media"]'::jsonb,3,'Variety increases reach.','original'),
('127.720.d.2.E',3,'A student uses an online collaboration tool to share a document with teammates across towns. This uses:','["evolving network and Internet resources to create and exchange work", "a chalkboard", "a typewriter", "a paper mailbox"]'::jsonb,0,'Networks enable collaboration.','original'),
('127.720.d.2.E',4,'A good reason to use cloud collaboration tools in a study is that they:','["cannot share files", "let several people edit and share work from anywhere", "prevent teamwork", "work only offline"]'::jsonb,1,'Cloud tools support remote collaboration.','original'),
('127.720.d.2.F',3,'A student video-chats with learners in another country to compare how technology is used there. This builds:','["confusion", "isolation", "cultural understanding and global awareness", "less knowledge"]'::jsonb,2,'Interaction across cultures builds awareness.','original'),
('127.720.d.2.F',4,'Interacting with students from other countries helps a technology learner to:','["avoid learning", "ignore diversity", "limit ideas", "see how different cultures solve similar problems"]'::jsonb,3,'Global perspective broadens solutions.','original'),
('127.720.d.2.G',3,'A student works with classmates to name a problem, propose a hypothesis and plan how to test it. This is:','["collaborating to identify a problem and strategies", "working alone silently", "copying answers", "skipping the problem"]'::jsonb,0,'Teams define problems together.','original'),
('127.720.d.2.G',4,'A strong group plan for solving a shared problem includes:','["no plan", "a clear problem statement, hypotheses and test strategies", "a random guess", "a deleted draft"]'::jsonb,1,'Plans pair problems with methods.','original'),
('127.720.d.2.H',3,'A student joins an online forum for programmers to ask questions, answer others and share code. This is participating:','["in a silent room", "in a locked folder", "in an electronic community as a learner and contributor", "in a paper club"]'::jsonb,2,'Online communities support learning and sharing.','original'),
('127.720.d.2.H',4,'Being a responsible member of an online technical community means:','["spamming", "mocking beginners", "hiding all answers", "giving accurate help and respecting others"]'::jsonb,3,'Good participation is respectful and useful.','original'),
('127.720.d.2.I',3,'A student volunteers to help seniors learn to use tablets at the library. This is:','["a meaningful activity in the larger community", "a hidden task", "a private hobby only", "a school punishment"]'::jsonb,0,'Community service applies tech skills.','original'),
('127.720.d.2.I',4,'Participating in community activities helps students apply technology to:','["only paper tasks", "real needs in society", "unrelated games", "no real needs"]'::jsonb,1,'Service connects learning to society.','original'),
('127.720.d.3.A',3,'A student uses the internet and shared databases to find current research for the study. This is:','["avoiding information", "copying a neighbor", "using network resources for research and resource sharing", "guessing"]'::jsonb,2,'Networks supply research resources.','original'),
('127.720.d.3.A',4,'Sharing research files with a mentor through a secure online folder is an example of:','["printing only", "losing data", "working offline only", "using network resources for resource sharing"]'::jsonb,3,'Secure sharing supports collaboration.','original'),
('127.720.d.3.B',3,'To find reliable articles quickly, a student uses exact phrases and filters by date. This is:','["applying appropriate search strategies", "ignoring results", "using only ads", "random clicking"]'::jsonb,0,'Good search strategy saves time.','original'),
('127.720.d.3.B',4,'In an independent study, a student puts a phrase in quotation marks while searching. That tells the search engine to:','["translate it", "look for that exact phrase", "ignore it", "delete it"]'::jsonb,1,'Quotation marks narrow results.','original'),
('127.720.d.3.C',3,'A student writes, "Does faster Wi-Fi improve online quiz scores?" This is:','["a final conclusion", "a citation", "posing a question related to a selected problem", "a file name"]'::jsonb,2,'Good questions guide study.','original'),
('127.720.d.3.C',4,'A hypothesis in an independent study should be:','["a random fact", "a finished conclusion", "an unrelated joke", "a testable statement related to the problem"]'::jsonb,3,'Hypotheses must be testable.','original'),
('127.720.d.3.D',3,'A student lists the author, title and web address for every source used. This is:','["acquiring information with source citations", "copying text", "losing information", "hiding sources"]'::jsonb,0,'Citations credit sources.','original'),
('127.720.d.3.D',4,'Citing sources in research protects the student from:','["all feedback", "plagiarism by crediting the original authors", "all research", "good grades"]'::jsonb,1,'Citations show where ideas came from.','original'),
('127.720.d.3.E',3,'A student saves an interview as audio, a poster as an image and notes as text. This is using:','["a single page", "no files", "a variety of file formats", "only one format"]'::jsonb,2,'Different content uses different file types.','original'),
('127.720.d.3.E',4,'Choosing the best file format for a video that must play on many devices means picking one that is:','["unreadable", "very old", "rarely supported", "widely supported"]'::jsonb,3,'Compatibility matters.','original'),
('127.720.d.4.A',3,'Before using a web article as a source, a student checks who wrote it, when it was updated and whether it matches other sources. This is:','["evaluating the design, functionality and accuracy of information", "skipping verification", "ignoring the author", "accepting everything"]'::jsonb,0,'Evaluate accuracy before using.','original'),
('127.720.d.4.A',4,'A website with no author, no date and many errors should be treated as:','["a peer-reviewed study", "unreliable and not a good source", "the best source", "an official record"]'::jsonb,1,'Weak credibility means weak source.','original'),
('127.720.d.4.B',3,'Gathering data from several sources, comparing it and documenting methods is:','["copying a friend", "random searching", "conducting systematic research", "guessing"]'::jsonb,2,'Systematic research is organized.','original'),
('127.720.d.4.B',4,'A systematic research process records:','["only the first result", "nothing at all", "only the final guess", "what was searched, found and concluded"]'::jsonb,3,'Records make research repeatable.','original'),
('127.720.d.4.C',3,'A student tries three different designs, learns from failures and chooses the best. This demonstrates:','["creative thinking and problem-solving", "avoiding choices", "copying", "giving up"]'::jsonb,0,'Trying alternatives builds solutions.','original'),
('127.720.d.4.C',4,'When the first solution fails, a creative thinker typically:','["quits", "adapts the idea and tries another approach", "blames others", "repeats the same failed step"]'::jsonb,1,'Persistence and adaptation solve problems.','original'),
('127.720.d.4.D',3,'A student uses a spreadsheet, a cloud drive and a mobile app together to collect and share survey data. This is integrating:','["only chalk", "unrelated tools", "productivity tools including network and mobile access", "only paper"]'::jsonb,2,'Tools can be combined for efficiency.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_91_v1'
from (values
('127.720.d.4.D',4,'Using a phone to enter survey answers that sync to a shared spreadsheet shows:','["offline work only", "no technology", "manual copying only", "mobile access combined with productivity tools"]'::jsonb,3,'Mobile and cloud tools integrate.','original'),
('127.720.d.4.E',3,'A student adds science and math content, such as charts of real data, to a multimedia presentation. This is:','["using enriched curricular content in a product", "using no data", "avoiding charts", "leaving it blank"]'::jsonb,0,'Content from other subjects enriches products.','original'),
('127.720.d.4.E',4,'Including accurate math and science in a technology project can:','["hide the topic", "strengthen the product with real content", "shorten it", "weaken it"]'::jsonb,1,'Real content adds value.','original'),
('127.720.d.4.F',3,'A student combines survey results from many websites into one new chart and summary. This is:','["copying one page", "hiding results", "synthesizing new information from electronic data", "deleting data"]'::jsonb,2,'Synthesis creates new information.','original'),
('127.720.d.4.F',4,'Synthesizing information requires the student to:','["ignore results", "copy one source", "summarize nothing", "combine sources into something new with clear conclusions"]'::jsonb,3,'Synthesis is more than copying.','original'),
('127.720.d.4.G',3,'A student reads a manual to install a network printer correctly. This is:','["reading and using technical documentation", "guessing the steps", "ignoring the manual", "avoiding instructions"]'::jsonb,0,'Technical documents guide tasks.','original'),
('127.720.d.4.G',4,'The best way to use a technical manual is to:','["ignore the diagrams", "follow its steps in order and note any warnings", "read only the last page", "skip the warnings"]'::jsonb,1,'Follow documentation carefully.','original'),
('127.720.d.4.H',3,'A student writes a one-page guide for classmates on how to set up the project app. This is:','["deleting notes", "writing a poem", "writing simple technical documentation for an audience", "drawing a cartoon"]'::jsonb,2,'Documentation is written for its readers.','original'),
('127.720.d.4.H',4,'Technical documentation for beginners should use:','["long paragraphs", "no examples", "jargon only", "clear steps and plain language"]'::jsonb,3,'Know your audience.','original'),
('127.720.d.5.A',3,'A student studies why copying an online photo without permission can break copyright law. This is discussing:','["intellectual property and copyright laws", "font choices", "keyboard shortcuts", "paper sizes"]'::jsonb,0,'IP laws govern use of others'' work.','original'),
('127.720.d.5.A',4,'Posting a classmate''s personal photo online without asking raises concerns about:','["file size", "privacy and consent", "paper weight", "screen brightness"]'::jsonb,1,'Sharing information requires consent.','original'),
('127.720.d.5.B',3,'A student gets permission and cites the source before using a chart from a report. This models:','["spamming", "hacking", "ethical acquisition and use of digital information", "plagiarism"]'::jsonb,2,'Ethical use includes permission and credit.','original'),
('127.720.d.5.B',4,'Which action models ethical use of digital information?','["Downloading paid work for free", "Sharing a stolen password", "Claiming others'' work as your own", "Using licensed images and crediting the creator"]'::jsonb,3,'Ethical use respects owners.','original'),
('127.720.d.5.C',3,'A student remixes a video using a clip they have permission to use and credits the owner. This models:','["respect for intellectual property when editing media", "avoiding credit", "stealing", "ignoring rights"]'::jsonb,0,'Editing respects creators'' rights.','original'),
('127.720.d.5.C',4,'Before editing a photo made by someone else, a student should:','["crop out the credit", "check the license or get permission", "remove the metadata only", "assume it''s free"]'::jsonb,1,'Permission comes first.','original'),
('127.720.d.5.D',3,'A student uses school computers only for approved work, installs only licensed programs and follows posted rules. This is:','["piracy", "misuse", "proper etiquette and responsible use of software", "reckless use"]'::jsonb,2,'Responsible use follows rules.','original'),
('127.720.d.5.D',4,'Knowledge of acceptable use policies helps users avoid:','["all learning", "all work", "all technology", "violations that could cost them access or cause harm"]'::jsonb,3,'Policies set expectations.','original'),
('127.720.d.5.E',3,'Using strong passwords and not clicking unknown links are:','["best practices for information security", "risky shortcuts", "unneeded steps", "bad habits"]'::jsonb,0,'Basic habits protect data.','original'),
('127.720.d.5.E',4,'Enabling two-factor authentication on an account improves security because it:','["hides the user''s name", "requires a second proof of identity", "disables the account", "removes the password"]'::jsonb,1,'A second factor blocks stolen passwords.','original'),
('127.720.d.5.F',3,'A student keeps user guides, project notes and help files organized in a folder. This is:','["losing notes", "hiding documents", "maintaining a technical documentation library", "deleting files"]'::jsonb,2,'Documentation libraries support future work.','original'),
('127.720.d.5.F',4,'A technical documentation library helps a student because it:','["wastes space", "has no purpose", "hides information", "keeps reference material easy to find and reuse"]'::jsonb,3,'Organized references save time.','original'),
('127.720.d.5.G',3,'A student studies how smartphones changed communication and what privacy concerns resulted. This is investigating:','["technology''s social and ethical effects", "only cable colors", "only hardware prices", "only battery types"]'::jsonb,0,'Technology affects society.','original'),
('127.720.d.5.G',4,'A social ramification of social media technology is:','["no communication", "new concerns about privacy and misinformation", "less data", "no change in society"]'::jsonb,1,'Tech brings social effects and ethical questions.','original'),
('127.720.d.6.A',3,'A student correctly uses a keyboard, a scanner and a drawing tablet, and saves files in the right operating system folder. This shows:','["no skill", "random clicking", "knowledge and appropriate use of input devices and operating systems", "avoiding computers"]'::jsonb,2,'Technical operation skills are basic.','original'),
('127.720.d.6.A',4,'Which shows appropriate use of an operating system?','["Saving everything on the desktop with random names", "Deleting system files", "Ignoring updates", "Organizing files in clearly named folders"]'::jsonb,3,'Good file management matters.','original'),
('127.720.d.6.B',3,'A student picks a graphics editor for a poster and a spreadsheet for data. This is:','["selecting appropriate digital tools", "wasting time", "copying", "random choosing"]'::jsonb,0,'Pick the tool that fits the task.','original'),
('127.720.d.6.B',4,'Acquiring a digital tool for a project should include checking that it:','["is the newest", "fits the task, the budget and the license terms", "is the cheapest only", "is the biggest"]'::jsonb,1,'Evaluate tools before adopting them.','original'),
('127.720.d.6.C',3,'A file made on a Mac won''t open on a Windows PC, so the student saves it in a shared format. This is:','["deleting the file", "ignoring problems", "adjusting for platform compatibility", "blaming the user"]'::jsonb,2,'Compatibility fixes keep work usable.','original'),
('127.720.d.6.C',4,'Before sharing a project with another school, a student should confirm that:','["the files are huge", "the files are hidden", "the files are renamed randomly", "the files open on the other school''s systems"]'::jsonb,3,'Test compatibility.','original'),
('127.720.d.6.D',3,'A student names files with a clear pattern like project_v2_2026-11-15. This follows:','["appropriate naming conventions", "random names", "blank names", "no rules"]'::jsonb,0,'Consistent names help organization.','original'),
('127.720.d.6.D',4,'Using correct technology terms in documentation and labels helps teammates to:','["lose files", "understand the project quickly and avoid mistakes", "be confused", "skip steps"]'::jsonb,1,'Consistent terms prevent errors.','original'),
('127.721.d.1.A',3,'Maya is a second-year independent study student who reuses skills from earlier courses to sketch a brand-new fitness-tracker interface. Her approach drives:','["a copy of a competitor''s app", "a stalled project", "creative design of a new technology product", "unneeded paperwork"]'::jsonb,2,'Existing knowledge feeds creative design.','original'),
('127.721.d.1.A',4,'A second-year independent study student wants to promote creativity in a new product. The strongest starting move is to:','["skip research entirely", "wait for a teacher to supply the idea", "clone the top app exactly", "build on prior skills to answer an unmet user need"]'::jsonb,3,'Creativity grows from skills plus need.','original'),
('127.721.d.1.B',3,'A mentor asks a student to set weekly checkpoints and scan industry blogs each month. The student is expected to:','["track trends and manage timelines", "avoid reviewing progress", "remove all deadlines", "stop researching"]'::jsonb,0,'Trend tracking and timelines guide advanced projects.','original'),
('127.721.d.1.B',4,'At a monthly checkpoint, the student compares work done with the original schedule. This review procedure is designed to:','["ignore the schedule", "evaluate progress and adjust the plan", "stop the study", "avoid accountability"]'::jsonb,1,'Reviews reveal gaps early.','original'),
('127.721.d.1.C',3,'Over a semester, a student posts dated progress screenshots and short video updates in a project folder. These items are:','["a system backup", "unrelated files", "electronic documentation that illustrates progress", "a project''s final report only"]'::jsonb,2,'Documentation traces development.','original'),
('127.721.d.1.C',4,'A mentor reviewing a student''s electronic project log should be able to see:','["only passwords", "only the title", "only the final grade", "what was done, when and what remains"]'::jsonb,3,'Logs make progress visible.','original'),
('127.721.d.1.D',3,'Before finalizing a prototype, a student shares it with a classmate and a working developer and records their suggestions. This is:','["gathering input from peers and professionals", "ignoring advice", "skipping review", "working in secret"]'::jsonb,0,'Input from both groups sharpens technology decisions.','original'),
('127.721.d.1.D',4,'A professional''s suggestion would require a major redesign. The student should respond by:','["deleting the prototype", "weighing the suggestion against the project goals and deciding", "never replying", "accepting everything blindly"]'::jsonb,1,'Respond thoughtfully, not automatically.','original'),
('127.721.d.1.E',3,'After a design review shows two bugs, the student patches them and begins the next stage. This reflects:','["hiding bugs", "permanent restarting", "revising as needed and then moving forward", "abandoning the study"]'::jsonb,2,'Revision then progress.','original'),
('127.721.d.1.E',4,'When a review finds no serious issues, the student should:','["discard the work", "wait without action", "repeat the stage endlessly", "advance to the next stage of the study"]'::jsonb,3,'Move on when criteria are met.','original'),
('127.721.d.1.F',3,'In an advanced study on databases, a student presents using words such as schema, query and normalization correctly. This shows:','["using terminology fit for the course", "guessing terms", "using slang", "avoiding vocabulary"]'::jsonb,0,'Course vocabulary signals mastery.','original'),
('127.721.d.1.F',4,'A student whose reports use course-specific technology terms accurately will find it easier to:','["avoid mentors", "be understood by professionals in the field", "skip documentation", "write less"]'::jsonb,1,'Accurate terms aid professional communication.','original'),
('127.721.d.1.G',3,'A student invents a script that merges data from three services into one dashboard no tutorial describes. This is an example of:','["a deleted file", "a routine task", "advanced innovation in technology applications", "a copy"]'::jsonb,2,'Original integrations show innovation.','original'),
('127.721.d.1.G',4,'Advanced creativity in technology applications is shown by a student who:','["follows only a checklist", "avoids all tools", "repeats a tutorial", "extends existing tools to solve a problem in a new way"]'::jsonb,3,'Innovation goes beyond tutorials.','original'),
('127.721.d.1.H',3,'Rafael is stuck on a failing script; he narrows the cause, then asks a peer and a mentor for ideas. He is practicing:','["solving problems with individual effort and outside input", "guessing", "blame shifting", "quitting"]'::jsonb,0,'Problem solving mixes self effort and collaboration.','original'),
('127.721.d.1.H',4,'When a technical problem continues after careful self-testing, a student who seeks peer and professional input is:','["wasting time", "using a sound problem-solving strategy", "cheating", "avoiding the problem"]'::jsonb,1,'Seeking help is good strategy.','original'),
('127.721.d.1.I',3,'A student building a data-entry tool for a clinic checks it against rules the health profession expects. The product must meet:','["no standards", "only personal taste", "standards identified by the selected profession", "random rules"]'::jsonb,2,'Professional standards guide design.','original'),
('127.721.d.1.I',4,'A product built for a selected profession is judged successful when it:','["has the most features", "is the shortest", "uses the newest font", "meets that profession''s standards and the user''s needs"]'::jsonb,3,'Standards and needs define success.','original'),
('127.721.d.1.J',3,'Priya identifies a problem, builds an original solution and releases it online. This is producing:','["original work published in an electronic format", "an unfinished draft", "a private note", "a copied product"]'::jsonb,0,'Original solutions are published.','original'),
('127.721.d.1.J',4,'A publishable independent study product must be:','["hidden", "original, solve an identified problem and be shared electronically", "a copy", "incomplete"]'::jsonb,1,'Originality and publication matter.','original'),
('127.721.d.2.A',3,'A student must submit a project in the required file type, size limit and color mode. Meeting these requirements is:','["optional", "ignoring rules", "formatting to defined output specifications", "random choice"]'::jsonb,2,'Specs define required formats.','original'),
('127.721.d.2.A',4,'If the output specification says the video must be 1080p and under 100 MB, the student should:','["ignore the limits", "exceed the size", "change the topic", "export the file to meet both requirements"]'::jsonb,3,'Meet each stated spec.','original'),
('127.721.d.2.B',3,'Near the end of the course, a student presents findings to professionals who ask questions and give critiques. The purpose is to obtain:','["comment and professional response from a panel", "a free lunch", "a blank evaluation", "a vacation"]'::jsonb,0,'Panels give expert response.','original'),
('127.721.d.2.B',4,'A student leaves a panel presentation with six written comments. The next step is to:','["argue later", "review them and decide which to apply", "ignore all of them", "throw them away"]'::jsonb,1,'Use feedback to improve.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
